// Fisher-Yates shuffle
function shuffle(arr){ for(let i=arr.length-1;i>0;i--){ const j=Math.floor(Math.random()*(i+1)); [arr[i],arr[j]]=[arr[j],arr[i]];} return arr; }

shuffle(QUESTIONS);

let idx = 0;
let answers = new Array(QUESTIONS.length).fill(null);

const card = document.getElementById('card');
const bar = document.getElementById('bar');
const resultDiv = document.getElementById('result');

function render(i){
  const q = QUESTIONS[i];
  card.innerHTML = '';
  const meta = document.createElement('div'); meta.className='meta'; meta.textContent = 'Pergunta ' + (i+1) + ' de ' + QUESTIONS.length;
  const title = document.createElement('div'); title.className='title'; title.textContent = q.q;
  card.appendChild(meta); card.appendChild(title);
  const choicesDiv = document.createElement('div'); choicesDiv.className='choices';
  const opts = q.choices.slice();
  shuffle(opts);
  opts.forEach((opt,ci)=>{
    const ch = document.createElement('div'); ch.className='choice'; ch.dataset.val = opt; ch.innerHTML = '<strong>' + String.fromCharCode(65+ci) + '.</strong> ' + opt;
    ch.addEventListener('click', ()=>{
      choicesDiv.querySelectorAll('.choice').forEach(x=>x.classList.remove('selected'));
      ch.classList.add('selected');
      answers[i] = opt;
      let ex = card.querySelector('.explain');
      if(!ex){ ex = document.createElement('div'); ex.className='explain'; card.appendChild(ex); }
      const correct = (opt === q.choices[q.answer]);
      ex.style.display = 'block';
      ex.innerHTML = '<strong>' + (correct ? 'Correto' : 'Incorreto') + '</strong><div style="margin-top:8px">' + q.explain + '</div>';
      updateProgress();
    });
    choicesDiv.appendChild(ch);
  });
  card.appendChild(choicesDiv);
  if(answers[i] !== null){
    const sel = Array.from(choicesDiv.children).find(c=>c.dataset.val === answers[i]);
    if(sel) sel.classList.add('selected');
    let ex = card.querySelector('.explain'); if(!ex){ ex = document.createElement('div'); ex.className='explain'; card.appendChild(ex); }
    ex.style.display = 'block'; ex.innerHTML = '<strong>Resposta registrada</strong><div style="margin-top:8px">' + q.explain + '</div>';
  }
  updateProgress();
}

function updateProgress(){ const answered = answers.filter(a=>a!==null).length; bar.style.width = Math.round((answered / QUESTIONS.length) * 100) + '%'; }

document.getElementById('prev').addEventListener('click', ()=>{ if(idx>0){ idx--; render(idx); window.scrollTo({top:0,behavior:'smooth'}); } });
document.getElementById('next').addEventListener('click', ()=>{ if(idx<QUESTIONS.length-1){ idx++; render(idx); window.scrollTo({top:0,behavior:'smooth'}); } });
document.getElementById('reset').addEventListener('click', ()=>{ if(!confirm('Zerar respostas e reiniciar?')) return; answers = new Array(QUESTIONS.length).fill(null); idx = 0; shuffle(QUESTIONS); render(idx); updateProgress(); resultDiv.style.display='none'; });
document.getElementById('finish').addEventListener('click', ()=>{ if(!confirm('Finalizar e ver resultado?')) return; let correct = 0, answered = 0; for(let i=0;i<QUESTIONS.length;i++){ if(answers[i]===null) continue; answered++; if(answers[i] === QUESTIONS[i].choices[QUESTIONS[i].answer]) correct++; } const wrong = answered - correct; const percent = Math.round((correct / QUESTIONS.length) * 100); resultDiv.style.display='block'; resultDiv.innerHTML = '<strong>Resultado:</strong><div class="card"><div>Acertos: '+correct+' — Erros: '+wrong+' — Não respondidas: '+(QUESTIONS.length-answered)+' — Percentual sobre total: '+percent+'%</div></div>'; resultDiv.scrollIntoView(); });

// initial render
render(0);
